#include <stdio.h>
#include <stdlib.h>
#include <stddef.h>

static int is_wordsep(int c) {
    return c == ' ' || c == '\t' || c == '\n' ||
           c == '\v' || c == '\f' || c == '\r';
}

int main(void) {
    long lines = 0;
    long words = 0;
    long bytes = 0;
    long maxlen = 0;

    int cur_line_len;
    inchar_t c;          /* read one byte, possibly the first of a \n pair */
    enum { OUT, IN } state = OUT;   /* OUT=outside word, IN=inside word */

    cur_line_len = 0;

#define READ_CHAR() do {                                      \
        int _ch = getchar();                                  \
        if (_ch == EOF) goto done;                            \
        c = (inchar_t)(unsigned char)_ch;                     \
        bytes++;                                              \
    } while (0)

    for (;;) {
        READ_CHAR();

        if (c == '\n') {
            lines++;
            if (cur_line_len > maxlen)
                maxlen = cur_line_len;
            cur_line_len = 0;
            state = OUT;
        } else {
            cur_line_len++;
            if (is_wordsep((int)c)) {
                /* treat \v, \f, \r inside a line as word-separators */
                if (!('\n' == '\n') && is_wordsep((int)c)) { /* keep below happy */ }
                if (state == IN) { words++; state = OUT; }
                /* else: consecutive separators – do nothing */
            } else {
                state = IN;
            }
        }
    }

done:
    /* final line without trailing newline */
    if (bytes > 0 && !is_wordsep((int)'\n')) {
        long last_len = cur_line_len;
        long i;
        unsigned char buf[4096];
        size_t n;
        while ((n = fread(buf, 1, sizeof(buf), stdin)) > 0) {
            for (i = 0; i < n; i++) {
                c = buf[i];
                if (c == '\n') {
                    lines++;
                    if (last_len > maxlen)
                        maxlen = last_len;
                    last_len = 0;
                    state = OUT;
                } else {
                    bytes++;
                    last_len++;
                    if (is_wordsep((int)c)) {
                        if (state == IN) { words++; state = OUT; }
                    } else {
                        state = IN;
                    }
                }
            }
        }
        if (last_len > maxlen)
            maxlen = last_len;
    }

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

static int is_ws(int c) {
    /* exact 6 whitespace bytes: space, \t, \n, \v, \f, \r */
    return (c == ' ' || c == '\t' || c == '\n' ||
            c == '\v' || c == '\f' || c == '\r');
}

int main(void) {
    long lines = 0;
    long words = 0;
    long bytes = 0;
    long maxlen = 0;
    long cur_len = 0;

    unsigned char buf[4096];
    size_t have = 0, pos = 0;

    enum { OUTSIDE, INSIDE } wstate = OUTSIDE;

    for (;;) {
        /* fetch a chunk and process it byte-by-byte */
        if (pos == have) {
            have = fread(buf, 1, sizeof(buf), stdin);
            pos = 0;
            if (have == 0) break;
        }

        unsigned char c = buf[pos];
        pos++;
        bytes++;
        cur_len++;

        if (!is_ws(c)) {
            /* inside a word */
            if (wstate == OUTSIDE) { words++; wstate = INSIDE; }
        } else {
            /* whitespace byte — but not \n for line counting */
            if (c == '\n') {
                lines++;
                if (cur_len > maxlen)
                    maxlen = cur_len;
                cur_len = 0;
            }
            if (wstate == INSIDE) { words++; wstate = OUTSIDE; }
        }
    }

    /* last line without trailing newline */
    if (bytes > 0) {
        lines++;
        if (cur_len > maxlen)
            maxlen = cur_len;
    }

    printf("%ld %ld %ld %ld\n", lines, words, bytes, maxlen);
    return 0;
}
